generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?count WHERE {
  {
    SELECT ("Goal" AS ?category) (COUNT(DISTINCT ?goal) AS ?count)
    WHERE { ?goal a wm:InvestmentGoal . }
  }
  UNION
  {
    SELECT ("Holding" AS ?category) (COUNT(DISTINCT ?holding) AS ?count)
    WHERE { ?holding a wm:PortfolioHolding . }
  }
  UNION
  {
    SELECT ("CashFlow" AS ?category) (COUNT(DISTINCT ?cf) AS ?count)
    WHERE { ?cf a wm:CashFlow . }
  }
  UNION
  {
    SELECT ("Rebalance" AS ?category) (COUNT(DISTINCT ?reb) AS ?count)
    WHERE { ?reb a wm:RebalancingAction . }
  }
  UNION
  {
    SELECT ("Scenario" AS ?category) (COUNT(DISTINCT ?sc) AS ?count)
    WHERE { ?sc a wm:MarketScenario . }
  }
}

generate.final_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizonLabel ?goalCount ?holdingCount ?cashFlowCount ?rebalanceCount ?scenarioCount WHERE {
  ?timeHorizon a wm:TimeHorizon .
  OPTIONAL { ?timeHorizon rdfs:label ?timeHorizonLabel . }

  {
    SELECT ?timeHorizon (COUNT(DISTINCT ?goal) AS ?goalCount) WHERE {
      ?timeHorizon wm:hasInvestmentGoal ?goal .
      ?goal a wm:InvestmentGoal .
    } GROUP BY ?timeHorizon
  }
  OPTIONAL {
    SELECT ?timeHorizon (COUNT(DISTINCT ?holding) AS ?holdingCount) WHERE {
      ?timeHorizon wm:hasContextValue ?holding .
      ?holding a wm:PortfolioHolding .
    } GROUP BY ?timeHorizon
  }
  OPTIONAL {
    SELECT ?timeHorizon (COUNT(DISTINCT ?cf) AS ?cashFlowCount) WHERE {
      ?timeHorizon wm:hasContextValue ?cf .
      ?cf a wm:CashFlow .
    } GROUP BY ?timeHorizon
  }
  OPTIONAL {
    SELECT ?timeHorizon (COUNT(DISTINCT ?reb) AS ?rebalanceCount) WHERE {
      ?timeHorizon wm:hasContextValue ?reb .
      ?reb a wm:RebalancingAction .
    } GROUP BY ?timeHorizon
  }
  OPTIONAL {
    SELECT ?timeHorizon (COUNT(DISTINCT ?sc) AS ?scenarioCount) WHERE {
      ?timeHorizon wm:hasMarketScenario ?sc .
      ?sc a wm:MarketScenario .
    } GROUP BY ?timeHorizon
  }
}

